// --- Static Polymorphism via Policy-Based Design ---
// Behavior chosen at compile time (Zero overhead)

struct DiskPolicy { void log() {} };
struct NetworkPolicy { void log() {} };

template <typename LoggerPolicy>
class Service {
    LoggerPolicy policy;
public:
    void execute() {
        // Direct method call, resolved statically.
        policy.log();
    }
};

// Compiler generates specialized Service classes
// Service<DiskPolicy> S1;
// Service<NetworkPolicy> S2;


// --- Template Metaprogramming for Compile-Time Calculation ---
// Calculation occurs during compilation; results injected as constants

// General recursive template
template <int N>
struct Factorial {
    static constexpr int value = N * Factorial<N - 1>::value;
};

// Specialization (Base Case)
template <>
struct Factorial<0> {
    static constexpr int value = 1;
};

// 'Result' is a hardcoded constant (720) in the final binary
constexpr int Result = Factorial<6>::value;


// --- CRTP (Curiously Recurring Template Pattern) for Static Interfaces ---
// Avoids virtual tables while enforcing interface structure

template <typename Derived>
class Base {
public:
    void call_impl() {
        // Compile-time static cast forces dispatch
        static_cast<Derived*>(this)->implementation();
    }
};

class Concrete : public Base<Concrete> {
public:
    // Required method enforced by Base
    void implementation() {}
};
